+
+for (const state of ['normal', 'failed', 'retrying']) {
+  assert(controls(state).canSave, `${state}: saving remains available`);
+}
+
+// Exercise the same render and click handlers used by the page.
+const elements = Object.fromEntries(['meal', 'amount', 'status', 'retry', 'save']
+  .map(id => [id, { value: '', disabled: false, textContent: '' }]));
+vm.runInNewContext(fs.readFileSync('app.js', 'utf8'), {
