+});
+elements.meal.value = 'Homemade soup';
+elements.amount.value = '2 bowls';
+elements.retry.onclick();
+assert.equal(elements.meal.disabled, false, 'Retry must leave meal description editable');
+assert.equal(elements.amount.disabled, false, 'Retry must leave manual amount editable');
+assert.equal(elements.save.disabled, false);
+assert.equal(elements.meal.value, 'Homemade soup');
+assert.equal(elements.amount.value, '2 bowls');
+assert.equal(elements.status.textContent, 'Estimating nutrition…');
+elements.amount.value = '3 bowls';
+elements.save.onclick();
+assert.equal(elements.status.textContent, 'Meal saved.');
+elements.retry.onclick();
+assert.equal(elements.amount.value, '3 bowls', 'Another retry preserves newer manual input');
+assert.equal(elements.status.textContent, 'Estimating nutrition…');
+assert(controls('normal').canEdit);
+assert.equal(controls('normal').message, 'Estimate ready. Meal not saved.');
+console.log('checks passed');

